#!/usr/bin/env python3
import sys
import re
from Bio import SeqIO

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    fasta_path = sys.argv[1]
    gene_pattern = re.compile(r'\[gene=([^]]+)\]')

    with open(fasta_path) as handle:
        for record in SeqIO.parse(handle, "fasta"):
            header = record.description
            match = gene_pattern.search(header)
            if not match:
                continue  # skip if no gene tag found
            gene = match.group(1)
            seq = str(record.seq).upper()
            length = len(seq)
            if length == 0:
                gc_percent = 0.0
            else:
                gc_count = seq.count('G') + seq.count('C')
                gc_percent = (gc_count / length) * 100
            print(f"{gene}\t{gc_percent:.2f}")

if __name__ == "__main__":
    main()

