import sys
import re
from Bio import SeqIO

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    fasta_path = sys.argv[1]
    gene_re = re.compile(r'\[gene=([^\]]+)\]')

    for record in SeqIO.parse(fasta_path, "fasta"):
        match = gene_re.search(record.description)
        if not match:
            continue  # skip if no gene tag found
        gene = match.group(1)

        # Translate from the first base, stop at the first stop codon
        protein = record.seq.translate(to_stop=True)
        length = len(protein)

        print(f"{gene}\t{length}")

if __name__ == "__main__":
    main()

