#!/usr/bin/env python3
import sys
from Bio import SeqIO

def find_orfs(seq, strand):
    """Return list of (start, end, length) for ORFs on given sequence."""
    stop_codons = {"TAA", "TAG", "TGA"}
    orfs = []
    n = len(seq)
    for frame in range(3):
        i = frame
        while i <= n - 3:
            codon = seq[i:i+3]
            if codon == "ATG":
                start = i
                for j in range(i+3, n-2, 3):
                    codon2 = seq[j:j+3]
                    if codon2 in stop_codons:
                        end = j + 2
                        length = end - start + 1
                        orfs.append((start, end, length))
                        break
            i += 3
    return orfs

def main():
    if len(sys.argv) != 2:
        sys.exit("Usage: script.py <fasta_file>")
    fasta_path = sys.argv[1]
    # Read single record FASTA
    records = list(SeqIO.parse(fasta_path, "fasta"))
    if not records:
        sys.exit("No sequence found in FASTA.")
    seq = str(records[0].seq).upper()
    n = len(seq)

    best = None  # (start, end, strand, length)

    # Forward strand
    for start, end, length in find_orfs(seq, "+"):
        if best is None or length > best[3]:
            best = (start, end, "+", length)

    # Reverse strand
    rev_seq = str(records[0].seq.reverse_complement()).upper()
    for rc_start, rc_end, length in find_orfs(rev_seq, "-"):
        # Map reverse complement coordinates back to forward strand (0‑based)
        fwd_start = n - rc_end   # corresponds to forward coordinate (0‑based)
        fwd_end   = n - rc_start
        # Convert to 1‑based inclusive coordinates
        start_1b = min(fwd_start, fwd_end) + 1
        end_1b   = max(fwd_start, fwd_end) + 1
        # Length is same as in reverse complement
        if best is None or length > best[3]:
            best = (start_1b, end_1b, "-", length)

    if best is None:
        sys.exit()  # No ORF found, print nothing
    # Ensure start <= end
    start, end, strand, length = best
    if start > end:
        start, end = end, start
    print(f"{start} {end} {strand} {length}")

if __name__ == "__main__":
    main()

