#!/usr/bin/env python3
import sys
from collections import Counter

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    path = sys.argv[1]
    feature_counts = Counter()
    total_cds_bp = 0

    with open(path, "r") as f:
        for line in f:
            line = line.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            parts = line.split("\t")
            if len(parts) < 5:
                continue  # not enough columns for a valid GFF3 entry
            feature_type = parts[2]
            feature_counts[feature_type] += 1
            if feature_type == "CDS":
                try:
                    start = int(parts[3])
                    end = int(parts[4])
                    total_cds_bp += end - start + 1
                except ValueError:
                    pass  # ignore lines where start/end are not integers

    for ft in sorted(feature_counts):
        print(f"{ft}\t{feature_counts[ft]}")
    print(f"total_cds_bp\t{total_cds_bp}")

if __name__ == "__main__":
