#!/usr/bin/env python3
import sys

def main():
    if len(sys.argv) < 2:
        return
    vcf_path = sys.argv[1]

    kept = 0
    snv = 0
    indel = 0
    trans = 0
    transv = 0

    with open(vcf_path, 'r') as f:
        for line in f:
            if line.startswith('#'):
                continue
            fields = line.rstrip('\n').split('\t')
            if len(fields) < 8:
                continue

            chrom, pos, vid, ref, alt, qual, filt, info = fields[:8]

            # FILTER
            if filt != 'PASS':
                continue

            # QUAL
            try:
                qual_val = float(qual)
            except ValueError:
                continue
            if qual_val < 30:
                continue

            # DP
            dp_val = None
            for part in info.split(';'):
                if part.startswith('DP='):
                    try:
                        dp_val = int(part[3:])
                    except ValueError:
                        dp_val = None
                    break
            if dp_val is None or dp_val < 10:
                continue

            # Record passes all filters
            kept += 1

            # Process each ALT allele separately
            for allele in alt.split(','):
                if len(ref) == 1 and len(allele) == 1:
                    snv += 1
                    r = ref.upper()
                    a = allele.upper()
                    if r == a:
                        continue
                    if (r == 'A' and a == 'G') or (r == 'G' and a == 'A') or \
                       (r == 'C' and a == 'T') or (r == 'T' and a == 'C'):
                        trans += 1
                    else:
                        transv += 1
                else:
                    indel += 1

    # Compute transition/transversion ratio
    if transv > 0:
        ratio = trans / transv
    else:
        ratio = 0.0

    print(f'kept={kept} snv={snv} indel={indel} titv={ratio:.3f}')

if __name__ == '__main__':
    main()
