#!/usr/bin/env python3
import sys
from Bio import SeqIO

def main():
    if len(sys.argv) < 2:
        sys.exit("Usage: script.py <fastq_file>")

    fastq_path = sys.argv[1]

    total_reads = 0
    pass_q20 = 0
    sum_means = 0.0

    try:
        with open(fastq_path, "rt") as handle:
            for record in SeqIO.parse(handle, "fastq"):
                total_reads += 1
                phred = record.letter_annotations.get("phred_quality", [])
                if not phred:
                    continue  # skip records without quality scores
                mean_quality = sum(phred) / len(phred)
                sum_means += mean_quality
                if mean_quality >= 20.0:
                    pass_q20 += 1
    except FileNotFoundError:
        sys.exit(f"File not found: {fastq_path}")
    except Exception as e:
        sys.exit(f"Error processing FASTQ: {e}")

    if total_reads > 0:
        mean_q = sum_means / total_reads
    else:
        mean_q = 0.0

    print(f"reads={total_reads} pass_q20={pass_q20} mean_q={mean_q:.2f}")

if __name__ == "__main__":
    main()
